changeSet.sql:
CREATE TABLE CatalogoAlergenos (
idAlergeno          INT AUTO_INCREMENT NOT NULL,
nombreAlergeno      VARCHAR(255),
CONSTRAINT CatalogoAlergenosPK PRIMARY KEY (idAlergeno)
);

CREATE TABLE FrecuenciaAlimentos (
idAlimento      INT AUTO_INCREMENT NOT NULL,
alimento        VARCHAR(255),
CONSTRAINT FrecuenciaAlimentosPK PRIMARY KEY (idAlimento)
);

CREATE TABLE FrecuenciaOpciones (
idFrecuencia        INT AUTO_INCREMENT NOT NULL,
nombreFrecuencia    VARCHAR(255),
CONSTRAINT FrecuenciaOpcionesPK PRIMARY KEY (idFrecuencia)
);

CREATE TABLE EsquemaTratamiento (
idEsquema           INT PRIMARY KEY AUTO_INCREMENT,
semana              VARCHAR(10) NOT NULL,
dosis               DECIMAL(4, 2) NOT NULL,
descripcion         VARCHAR(255)
);
